insert into things (source_id, title, description, type_of_name, genre, person, "user", created_at) values ('wtaIFt4sSGlXdpTRt25SUk', 'Clownin’ Around ', 'A punk band where everyone is a clown! I know there’s already a band that dresses like clowns, OK? This is different. First, they ARE clowns; it’s not a costume. Second,they aren’t scary goth clowns. They are traditional clowns with polkadots and red noses and big shoes. Maybe one of them is a sad clown. Maybe one is a hobo clown. Their music is pretty standard punk but it’s only about clowns. Note: Clownin’ Around is staunchly against the use of animals in circuses because who needs animals when you have CLOWNS?!  ', 'Band', 'Punk', NULL, '{"name":"Emily Endress","email":"emendress@gmail.com","image":"https://lh3.googleusercontent.com/a/ACg8ocImeIKvcB3wsEKu6Y6jgbzbb4nqYdZ1_pQ1QZVqIF1bHjfkgMQt=s96-c"}', '2025-07-23T18:56:32Z') on conflict (source_id) do nothing;
